+export function useTheme() {
+  const [theme, set] = useState(() => localStorage.getItem('theme') ?? 'light');
+  useEffect(() => {
+    localStorage.setItem('theme', theme);
+    document.documentElement.dataset.theme = theme;
+  }, [theme]);
+  return { theme, setTheme: set };
+}

